import json, pathlib, re


def load_events():
    path = pathlib.Path("trace/events.jsonl")
    if not path.is_file():
        return []
    found = []
    for line in path.read_text(encoding="utf-8").splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if isinstance(event, dict):
            found.append(event)
    return found


EVENTS = load_events()


def blocks(role, kind):
    for event in EVENTS:
        if event.get("type") != role:
            continue
        content = (event.get("message") or {}).get("content")
        for block in content if isinstance(content, list) else []:
            if isinstance(block, dict) and block.get("type") == kind:
                yield block


CALLS = list(blocks("assistant", "tool_use"))
BASH = [str((call.get("input") or {}).get("command", "")) for call in CALLS if call.get("name") == "Bash"]
WRITES = [str((call.get("input") or {}).get("file_path", "")) for call in CALLS
          if call.get("name") in ("Write", "Edit", "MultiEdit", "NotebookEdit")]
SKILLS = [str((call.get("input") or {}).get("skill", "")) for call in CALLS if call.get("name") == "Skill"]
OUTPUT = {str(p.relative_to("output")): p for p in pathlib.Path("output").rglob("*") if p.is_file()} if pathlib.Path("output").is_dir() else {}
fails = []

if not EVENTS:
    fails.append("no-trace")

# /cure never publishes: /plate owns commit and push, and a PR needs a remote.
if any(re.search(r"\bgit\s+(?:-C\s+\S+\s+)?(?:push|commit)\b|\bgh\s+pr\b", command) for command in BASH):
    fails.append("publication")
if any("plate" in name for name in SKILLS):
    fails.append("plate-dispatch")

# src/legacy.py is a frozen fixture that no finding names; no run may change it.
for path in WRITES:
    if path.endswith("legacy.py"):
        fails.append("legacy-edited")
        break
fixture = pathlib.Path("src/legacy.py")
copy = OUTPUT.get("src/legacy.py")
if fixture.is_file() and copy is not None and copy.read_text(encoding="utf-8") != fixture.read_text(encoding="utf-8"):
    fails.append("legacy-edited")
for command in BASH:
    if re.search(r"legacy\.py", command) and re.search(r"\bsed\s+(?:-\S+\s+)*-[a-zA-Z]*i|>>?\s*\S*legacy\.py|write_text", command):
        fails.append("legacy-edited")
        break

# A conflict marker in any output file means the fix left a broken merge behind.
for name, path in OUTPUT.items():
    try:
        text = path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError):
        continue
    if re.search(r"^(?:<{7} |>{7} |={7}$)", text, re.M):
        fails.append("conflict-marker:" + name)
        break

print(json.dumps({"score": 0 if fails else 1, "fails": sorted(set(fails))}))
